using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace Synkoz {
internal static class UiPolicyR20 {
 internal static bool Teensy;static readonly HashSet<Control> watched=new HashSet<Control>();static readonly Dictionary<Label,Tuple<int,string>> keys=new Dictionary<Label,Tuple<int,string>>();
 internal static double Snap(double angle){double nearest=Math.Round(angle/90)*90;return Math.Abs(nearest-angle)<=5?nearest:angle;}
 internal static int GridStep(int bars,int width){int step=1;while((double)bars/step>Math.Max(1,width/60))step*=2;return step;}
 internal static void KeyLabel(Label label,int key,string text){keys[label]=Tuple.Create(key,text);label.Text=(Teensy?"K"+key+" · ":"")+text;label.Disposed+=delegate{keys.Remove(label);};}
 internal static void Start(){Application.AddMessageFilter(new WheelFilter());Application.Idle+=delegate{foreach(var f in Application.OpenForms.Cast<Form>().ToArray())Watch(f);foreach(var pair in keys.ToArray()){string text=(Teensy?"K"+pair.Value.Item1+" · ":"")+pair.Value.Item2;if(pair.Key.Text!=text)pair.Key.Text=text;}};}
 internal static void Watch(Control c){if(!watched.Add(c))return;c.Disposed+=delegate{watched.Remove(c);};Action style=()=>{string t=c.Text.ToLowerInvariant();var b=c as Button;if(b!=null){Color color=t.StartsWith("appliquer")||t.StartsWith("valider")||t=="ok"||t.StartsWith("confirmer")?Color.SeaGreen:t.Contains("placer")||t.Contains("définir")||t.Contains("cadrage")?Color.SteelBlue:Color.Empty;if(!color.IsEmpty){b.UseVisualStyleBackColor=false;b.BackColor=color;b.ForeColor=Color.White;}}if(c is Label&&t.Contains("amplitude")){c.BackColor=Color.DarkOrange;c.ForeColor=Color.Black;}};style();c.TextChanged+=delegate{style();};c.ControlAdded+=delegate(object sender,ControlEventArgs e){Watch(e.Control);};foreach(Control child in c.Controls)Watch(child);}
 internal sealed class WheelFilter:IMessageFilter {
 public bool PreFilterMessage(ref Message m){if(m.Msg!=0x20a&&m.Msg!=0x20e)return false;var c=Control.FromChildHandle(m.HWnd);if(c==null)return false;int delta=(short)((m.WParam.ToInt64()>>16)&65535);bool horizontal=m.Msg==0x20e;for(Control p=c;p!=null;p=p.Parent){var scroll=p as ScrollableControl;if(scroll!=null&&scroll.AutoScroll&&(horizontal?scroll.HorizontalScroll.Visible:scroll.VerticalScroll.Visible)){var pos=scroll.AutoScrollPosition;int step=SystemInformation.MouseWheelScrollLines<0?scroll.ClientSize.Height:Math.Max(1,SystemInformation.MouseWheelScrollLines)*20;scroll.AutoScrollPosition=new Point(Math.Max(0,-pos.X+(horizontal?delta*step/120:0)),Math.Max(0,-pos.Y-(horizontal?0:delta*step/120)));return true;}if(p is TextBoxBase&&!(p.Parent is NumericUpDown)&&!(p.Parent is ComboBox)||p is ListBox||p is ListView||p is TreeView||p is DataGridView||p is ScrollBar)return false;}return true;}}
}
public sealed class AssistanceSettingsR20 {public bool Midi=true,Presets=true;}
public sealed partial class Montage {public AssistanceSettingsR20 AssistanceR20=new AssistanceSettingsR20();}
public sealed partial class EffectsForm936 {
 void InstallAssistanceR20(TableLayoutPanel shell){var settings=model.AssistanceR20;var row=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};var midi=AssistanceR19.Toggle("Aide au MIDI (Ctrl+M)",settings.Midi,v=>{settings.Midi=v;incomingCacheR19=null;model.Save();},"Évite le choix d’un canal sans CC pour une animation par CC. L’analyse peut consommer beaucoup de processeur. Réglage de ce projet.");var presets=AssistanceR19.Toggle("Preset intelligent (Ctrl+P)",settings.Presets,v=>{settings.Presets=v;model.Save();},"Analyse les possibilités uniquement au clic sur Presets. Réglage de ce projet.");row.Controls.Add(midi);row.Controls.Add(presets);shell.RowCount=3;shell.RowStyles.Add(new RowStyle(SizeType.Absolute,30));shell.Controls.Add(row,0,2);var filter=new AssistanceKeysR20(this,settings,()=>{incomingCacheR19=null;model.Save();});Application.AddMessageFilter(filter);var timer=new Timer{Interval=250};timer.Tick+=delegate{midi.Checked=settings.Midi;presets.Checked=settings.Presets;};timer.Start();Disposed+=delegate{timer.Dispose();Application.RemoveMessageFilter(filter);};}
 sealed class AssistanceKeysR20:IMessageFilter {readonly EffectsForm936 owner;readonly AssistanceSettingsR20 value;readonly Action change;internal AssistanceKeysR20(EffectsForm936 f,AssistanceSettingsR20 s,Action c){owner=f;value=s;change=c;}public bool PreFilterMessage(ref Message m){if(m.Msg!=0x100||Control.ModifierKeys!=Keys.Control)return false;var active=Form.ActiveForm;int depth=0;while(active!=null&&active!=owner&&depth++<32)active=WindowFocusR15.ParentR20(active);if(active!=owner&&!owner.ContainsFocus)return false;Keys key=(Keys)m.WParam.ToInt32();if(key==Keys.M)value.Midi=!value.Midi;else if(key==Keys.P)value.Presets=!value.Presets;else return false;change();return true;}}
}
}
